package cn.workpanel.module.aiwork.application;

import cn.workpanel.*;
import cn.workpanel.module.aiwork.domain.*;
import cn.workpanel.module.aiwork.infrastructure.*;
import cn.workpanel.module.attachment.application.AttachmentApplicationService;
import cn.workpanel.module.procedure.api.ProcedureAccess;
import cn.workpanel.module.review.api.ReviewApi;
import cn.workpanel.module.review.api.ReviewActors;
import cn.workpanel.module.task.*;
import cn.workpanel.shared.application.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;

/** 私有事项用例；所有写命令先锁实时身份，再锁事项，实现撤权与取消的确定提交顺序。 */
@Service
public class WorkService {
    private final WorkRepository repo;private final Db db;private final CurrentActors actors;private final CommandKeys keys;private final AttachmentApplicationService attachments;private final MemoryModel model;private final FileExtractor extractor;private final ProcedureAccess procedures;private final ReviewApi reviews;private final WorkPeople personnel;private final DeliveryService delivery;private final WorkAuthorizationPolicy authorizationPolicy;
    public final boolean enabled,executionEnabled;
    public boolean isEnabled(){return enabled;}
    public boolean isExecutionEnabled(){return executionEnabled;}
    public WorkService(WorkRepository repo,CurrentActors actors,CommandKeys keys,AttachmentApplicationService attachments,MemoryModel model,FileExtractor extractor,ProcedureAccess procedures,ReviewApi reviews,WorkPeople personnel,DeliveryService delivery,WorkAuthorizationPolicy authorizationPolicy,@Value("${app.ai-workbench-enabled:true}")boolean enabled,@Value("${app.ai-work-execution-enabled:false}")boolean executionEnabled){this.repo=repo;this.db=repo.database();this.actors=actors;this.keys=keys;this.attachments=attachments;this.model=model;this.extractor=extractor;this.procedures=procedures;this.reviews=reviews;this.personnel=personnel;this.delivery=delivery;this.authorizationPolicy=authorizationPolicy;this.enabled=enabled;this.executionEnabled=executionEnabled;}
    public Map<String,Object> authorizationPolicy(Actor actor){return authorizationPolicy.view(actors.fresh(actor));}
    public void lockAuthorizationPolicy(Actor actor){authorizationPolicy.row(actor,true);}
    public Map<String,Object> capabilities(Actor actor){Actor a=actors.fresh(actor);return Map.of("contractVersion",1,"enabled",enabled,"configured",model.configured(),"executionEnabled",executionEnabled,"imageEnabled",extractor.imagesAvailable(),"canCreateTask",WorkPolicy.canDispatch(a),"limits",AiFilePolicy.limits(),"actions",WorkPolicy.ACTIONS);}
    public Map<String,Object> list(Actor actor,int cursor,int limit){Actor a=actors.fresh(actor);Business.page(cursor,limit);var items=db.rows("SELECT id,title,state,version,plan_version,updated_at,result FROM ai_work_items WHERE company_id=? AND owner_id=? AND deleted_at IS NULL ORDER BY updated_at DESC,id LIMIT ? OFFSET ?",a.company(),a.id(),limit,cursor);for(var item:items){item.put("result",currentResult(a,db.read(item.get("result"))));if(((Number)item.get("plan_version")).intValue()>0)try{var plan=db.read(repo.plan(a,Db.str(item,"id"),((Number)item.get("plan_version")).intValue()).get("body"));procedures.validateSources(a,DeliveryService.maps(plan,"sources"));}catch(ApiError e){item.put("result",Map.of("summary","依据已更新，请重新核对"));}}return Map.of("contractVersion",1,"items",items,"nextCursor",items.size()==limit?cursor+limit:-1);}
    @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
    public Map<String,Object> get(Actor actor,String id){
        Actor a=actors.fresh(actor);var row=repo.owned(a,id,false);var result=new LinkedHashMap<>(row);result.put("contractVersion",1);result.put("planVersion",row.get("plan_version"));result.put("messages",repo.messages(a,id));
        var receipts=db.rows("SELECT step_key,result,created_at FROM ai_action_receipts WHERE company_id=? AND actor_id=? AND work_id=? ORDER BY created_at,step_key",a.company(),a.id(),id);
        // 正式业务引用每次重查权限；不从旧缓存泄露已失权任务详情。
        for(var receipt:receipts)receipt.put("result",currentResult(a,db.read(receipt.get("result"))));
        result.put("result",currentResult(a,db.read(row.get("result"))));
        result.put("receipts",receipts);var steps=db.rows("SELECT step_key,action,state,result,error_code FROM ai_work_steps WHERE company_id=? AND work_id=? ORDER BY plan_version,step_key",a.company(),id);for(var step:steps)step.put("result",currentResult(a,db.read(step.get("result"))));result.put("steps",steps);
        int v=((Number)row.get("plan_version")).intValue();if(v>0){var p=repo.plan(a,id,v);var plan=db.read(p.get("body"));boolean valid=actors.fingerprint(a).equals(p.get("permission_fingerprint"));try{if("WAITING_CONFIRMATION".equals(row.get("state")))validatePlan(a,p);else procedures.validateSources(a,DeliveryService.maps(plan,"sources"));}catch(ApiError e){valid=false;}
            for(var action:DeliveryService.maps(plan,"actions")){var payload=db.read(action.get("payload"));if(payload.get("taskId") instanceof String task)try{TaskAccess.readable(db,a,task,false);}catch(ApiError e){valid=false;}for(var similar:DeliveryService.maps(action,"similarTasks"))try{TaskAccess.readable(db,a,Db.str(similar,"id"),false);}catch(ApiError e){valid=false;}}
            result.put("planValid",valid);if(valid){if("WAITING_CONFIRMATION".equals(row.get("state"))){var waiting=db.rows("SELECT step_key FROM ai_work_steps WHERE company_id=? AND work_id=? AND plan_version=? AND state='WAITING'",a.company(),id,v).stream().map(s->Db.str(s,"step_key")).collect(java.util.stream.Collectors.toSet());var actions=DeliveryService.maps(plan,"actions");var visible=new ArrayList<Map<String,Object>>();for(int i=0;i<actions.size();i++)if(waiting.contains("action-"+(i+1)))visible.add(actions.get(i));plan.put("actions",visible);}result.put("plan",plan);}else result.put("result",Map.of("summary","办理条件已更新，请重新核对"));
            result.put("planHash",p.get("hash"));result.put("confirmationId",db.rows("SELECT id FROM ai_work_confirmations WHERE company_id=? AND work_id=? AND plan_version=? AND consumed_at IS NULL AND expires_at>now()",a.company(),id,v).stream().map(x->x.get("id")).findFirst().orElse(""));}
        result.put("eventsCursor",db.count("SELECT coalesce(max(sequence),0) FROM ai_work_events WHERE company_id=? AND work_id=?",a.company(),id));
        result.put("recoverable",Set.of("FAILED","PARTIAL","WAITING_INPUT","WAITING_CONFIRMATION").contains(row.get("state")));return result;
    }
    @Transactional public Map<String,Object> create(Actor actor,Map<String,Object> body,String key){Actor a=actors.locked(actor);requireEnabled();var input=WorkInput.parse(body,false);validateInput(a,input);
        var result=keys.execute(a,"work.create",key,body,()->{String id=Db.id();db.update("INSERT INTO ai_work_items(id,company_id,owner_id,title) VALUES (?,?,?,?)",id,a.company(),a.id(),input.text().isBlank()?"整理材料":input.text().substring(0,Math.min(40,input.text().length())));repo.append(a,id,input.body());for(String f:input.attachments())attachments.bind(a,f,"WORK",id);repo.step(a,id,0,"prepare-1","PREPARE",Map.of());repo.event(a,id);return Map.of("id",id);});return get(a,Db.str(result,"id"));}
    @Transactional public Map<String,Object> message(Actor actor,String id,Map<String,Object> body,String key){Actor a=actors.locked(actor);requireEnabled();var row=repo.owned(a,id,true);var input=WorkInput.parse(body,true);validateInput(a,input);
        keys.execute(a,"work.message:"+id,key,body,()->{WorkPolicy.version(row,body);if(Set.of("CANCELLED","CANCEL_REQUESTED").contains(row.get("state")))throw ApiError.conflict();if(db.count("SELECT count(*) FROM ai_work_steps WHERE company_id=? AND work_id=? AND state='UNKNOWN'",a.company(),id)>0)throw new ApiError(409,"OUTCOME_PENDING","正在核对办理结果，请稍候再补充，也可以停止后续办理");repo.cancelPending(a,id);repo.append(a,id,input.body());for(String f:input.attachments())attachments.bind(a,f,"WORK",id);int version=((Number)row.get("version")).intValue()+1;repo.step(a,id,((Number)row.get("plan_version")).intValue(),"prepare-"+version,"PREPARE",Map.of());repo.state(a,id,"QUEUED",Map.of("summary","正在整理要求…"));return Map.of("id",id);});return get(a,id);}
    @Transactional public Map<String,Object> confirm(Actor actor,String id,Map<String,Object> body,String key){Actor a=actors.locked(actor);requireEnabled();var row=repo.owned(a,id,true);Db.fields(body,"version","planVersion","planHash","confirmationId","actions");
        keys.execute(a,"work.confirm:"+id,key,body,()->{WorkPolicy.version(row,body);if(!"WAITING_CONFIRMATION".equals(row.get("state")))throw ApiError.conflict();int version=((Number)row.get("plan_version")).intValue();if(!(body.get("planVersion") instanceof Number n)||n.intValue()!=version)throw ApiError.conflict();var plan=repo.plan(a,id,version);var selected=Business.strings(body,"actions");validatePlan(a,plan,new HashSet<>(selected),true);if(!plan.get("hash").equals(body.get("planHash")))throw ApiError.conflict();
            Db.conflict(db.update("UPDATE ai_work_confirmations SET consumed_at=now() WHERE id=? AND company_id=? AND work_id=? AND plan_version=? AND plan_hash=? AND consumed_at IS NULL AND expires_at>now()",Db.required(body,"confirmationId"),a.company(),id,version,plan.get("hash")));
            if(selected.isEmpty())throw ApiError.bad("ACTION_REQUIRED","请选择要办理的操作");var steps=db.rows("SELECT step_key,action,dependencies FROM ai_work_steps WHERE company_id=? AND work_id=? AND plan_version=? AND state='WAITING'",a.company(),id,version);
            if(!steps.stream().map(s->Db.str(s,"step_key")).toList().containsAll(selected))throw ApiError.conflict();
            for(var step:steps)if(selected.contains(step.get("step_key")))for(String dependency:Business.strings(step,"dependencies"))if(!selected.contains(dependency)&&db.count("SELECT count(*) FROM ai_work_steps WHERE company_id=? AND work_id=? AND plan_version=? AND step_key=? AND state='SUCCEEDED'",a.company(),id,version,dependency)==0)throw ApiError.bad("DEPENDENCY_REQUIRED","请一并确认前置操作");
            for(var step:steps)if(selected.contains(step.get("step_key"))){if(step.get("action").equals("CREATE_TASK")&&!WorkPolicy.canDispatch(a))throw ApiError.forbidden();db.update("UPDATE ai_work_steps SET state='PENDING',payload=payload||'{\"confirmed\":true}'::jsonb WHERE company_id=? AND work_id=? AND plan_version=? AND step_key=?",a.company(),id,version,step.get("step_key"));}
            else db.update("UPDATE ai_work_steps SET state='SKIPPED' WHERE company_id=? AND work_id=? AND plan_version=? AND step_key=?",a.company(),id,version,step.get("step_key"));
            repo.state(a,id,"EXECUTING",Map.of("summary",executionEnabled?"正在办理…":"自动办理暂时关闭，内容已保留"));return Map.of("id",id);});return get(a,id);}
    @Transactional public Map<String,Object> command(Actor actor,String id,String action,Map<String,Object> body,String key){Actor a=actors.locked(actor);Db.fields(body,"version");keys.execute(a,"work."+action+":"+id,key,body,()->{var row=repo.owned(a,id,true);WorkPolicy.version(row,body);
        if(action.equals("retry")){requireEnabled();if(!Set.of("FAILED","PARTIAL","WAITING_CONFIRMATION").contains(row.get("state")))throw ApiError.conflict();int planVersion=((Number)row.get("plan_version")).intValue();boolean stalePlan=false;if(planVersion>0)try{validatePlan(a,repo.plan(a,id,planVersion));}catch(ApiError e){stalePlan=true;}if("WAITING_CONFIRMATION".equals(row.get("state"))&&!stalePlan)throw ApiError.conflict();if(stalePlan){repo.cancelPending(a,id);repo.step(a,id,planVersion,"prepare-retry-"+(((Number)row.get("version")).intValue()+1),"PREPARE",Map.of("resumePlanVersion",planVersion));repo.state(a,id,"QUEUED",Map.of("summary","办理条件已更新，正在重新核对"));}else{db.update("UPDATE ai_work_steps SET state='PENDING',attempts=0,next_run_at=now(),fence=fence+1,result='{}'::jsonb,error_code=NULL WHERE company_id=? AND work_id=? AND state='FAILED'",a.company(),id);repo.state(a,id,"QUEUED",Map.of("summary","正在继续办理…"));}}
        else{repo.cancelPending(a,id);repo.state(a,id,"CANCELLED",Map.of("summary","已停止后续办理，已办理的操作仍保留"));if(action.equals("delete")){db.update("UPDATE ai_work_items SET deleted_at=now(),result='{}' WHERE company_id=? AND id=?",a.company(),id);db.update("DELETE FROM ai_work_messages WHERE company_id=? AND work_id=?",a.company(),id);}}
        return Map.of("id",id,"state",action.equals("retry")?"QUEUED":"CANCELLED");});return action.equals("delete")?Map.of("id",id,"state","CANCELLED"):get(a,id);}
    public Map<String,Object> authorizationOptions(Actor actor,String action,String search,int cursor){Actor a=actors.fresh(actor);Business.page(cursor,30);if(search.length()>200)throw ApiError.bad("INVALID_SEARCH","搜索内容过长");
        if(action.equals("CREATE_TASK")){a.requireDispatch();var args=new ArrayList<Object>();args.add(a.company());args.addAll(Arrays.asList(a.scopeArgs()));args.add("%"+search+"%");args.add(cursor);return Map.of("items",db.rows("SELECT u.id,u.name AS label,coalesce(d.name,'') AS department,coalesce(t.name,'') AS team FROM users u LEFT JOIN departments d ON d.company_id=u.company_id AND d.id=u.department_id LEFT JOIN teams t ON t.company_id=u.company_id AND t.id=u.team_id WHERE u.company_id=? AND u.status='ACTIVE' AND ("+a.userScope("u")+") AND u.name ILIKE ? ORDER BY u.name,u.id LIMIT 30 OFFSET ?",args.toArray()));}
        if(action.equals("CHECK_DELIVERY")){var scope=Business.taskScope(a);var args=new ArrayList<Object>(scope.args());args.add("%"+search+"%");args.add(cursor);return Map.of("items",db.rows("SELECT t.id,t.title AS label FROM tasks t WHERE "+scope.sql()+" AND t.title ILIKE ? ORDER BY t.title,t.id LIMIT 30 OFFSET ?",args.toArray()));}
        if(!action.equals("SUBMIT_DELIVERY"))throw ApiError.bad("INVALID_ACTION","请选择支持的操作");
        return Map.of("items",db.rows("SELECT DISTINCT t.id,t.title AS label FROM tasks t WHERE t.company_id=? AND t.phase IN ('RECEIVED','FEEDBACK') AND (t.owner_id=? OR EXISTS(SELECT 1 FROM task_participants c WHERE c.task_id=t.id AND c.company_id=t.company_id AND c.user_id=?)) AND t.title ILIKE ? ORDER BY t.title,t.id LIMIT 30 OFFSET ?",a.company(),a.id(),a.id(),"%"+search+"%",cursor));
    }
    public List<Map<String,Object>> authorizations(Actor actor){Actor a=actors.fresh(actor);var policyRow=authorizationPolicy.row(a,false);var rules=authorizationPolicy.rules(policyRow);var rows=db.rows("SELECT id,action,scope,expires_at,revoked_at,version,policy_revision FROM ai_work_authorizations WHERE company_id=? AND owner_id=? ORDER BY created_at DESC",a.company(),a.id());for(var row:rows){var scope=db.read(row.get("scope"));var labels=new ArrayList<String>();for(String id:Business.strings(scope,"ownerIds")){var person=db.rows("SELECT * FROM users WHERE company_id=? AND id=?",a.company(),id);if(!person.isEmpty()&&a.canSeeUser(person.getFirst()))labels.add(Db.str(person.getFirst(),"name"));else labels.add("人员已不可用");}for(String id:Business.strings(scope,"taskIds"))try{labels.add(Db.str(TaskAccess.readable(db,a,id,false),"title"));}catch(ApiError e){labels.add("任务已不可用");}row.put("scopeLabels",labels);row.put("effective",row.get("revoked_at")==null&&((java.sql.Timestamp)row.get("expires_at")).toInstant().isAfter(Instant.now())&&Objects.equals(row.get("policy_revision"),policyRow.get("ai_authorization_revision"))&&rules.allows(Db.str(row,"action")));}return rows;}
    @Transactional public Map<String,Object> authorize(Actor actor,Map<String,Object> body,String key){Actor a=actors.locked(actor);var policyRow=authorizationPolicy.row(a,true);var policy=authorizationPolicy.rules(policyRow);Db.fields(body,"action","scope","expiresAt");String action=Db.required(body,"action");if(!Set.of("CREATE_TASK","SUBMIT_DELIVERY").contains(action))throw ApiError.bad("INVALID_ACTION","这项操作暂不支持自动授权");if(action.equals("CREATE_TASK"))a.requireDispatch();if(!policy.allows(action))throw ApiError.bad("AUTHORIZATION_RESTRICTED","公司暂未开放这项自动授权");var scope=db.read(body.get("scope"));Db.fields(scope,"ownerIds","taskIds","maxActions");var owners=Business.strings(scope,"ownerIds");var tasks=Business.strings(scope,"taskIds");if(owners.size()+tasks.size()>policy.objects() || action.equals("CREATE_TASK")&&!tasks.isEmpty() || action.equals("SUBMIT_DELIVERY")&&!owners.isEmpty())throw ApiError.bad("INVALID_SCOPE","授权对象超出公司允许的范围");if(action.equals("CREATE_TASK")&&owners.isEmpty()||action.equals("SUBMIT_DELIVERY")&&tasks.isEmpty())throw ApiError.bad("INVALID_SCOPE","请选择具体人员或任务");for(String id:owners){var user=db.one("SELECT * FROM users WHERE company_id=? AND id=? AND status='ACTIVE'",a.company(),id);if(!a.canSeeUser(user))throw ApiError.forbidden();}for(String id:tasks){var t=TaskAccess.readable(db,a,id,false);var roles=TaskRoles.resolve(db,a,t);if(!roles.contains(TaskStateMachine.Role.PARTICIPANT))throw ApiError.forbidden();}
        Object max=scope.getOrDefault("maxActions",policy.actions());if(!(max instanceof Number count)||count.doubleValue()!=count.intValue()||count.intValue()<1||count.intValue()>policy.actions())throw ApiError.bad("INVALID_SCOPE","每批数量超出公司允许的范围");scope.put("maxActions",count.intValue());Instant expiry;try{expiry=OffsetDateTime.parse(Db.required(body,"expiresAt")).toInstant();}catch(Exception e){throw ApiError.bad("INVALID_DATE","请选择授权到期时间");}if(!expiry.isAfter(Instant.now())||expiry.isAfter(Instant.now().plus(Duration.ofDays(policy.days()))))throw ApiError.bad("INVALID_DATE","授权有效期最长为 "+policy.days()+" 天");
        return keys.execute(a,"work.authorize",key,body,()->{String id=Db.id();db.update("INSERT INTO ai_work_authorizations(id,company_id,owner_id,action,scope,expires_at,policy_revision) VALUES (?,?,?,?,?::jsonb,?::timestamptz,?)",id,a.company(),a.id(),action,db.write(scope),expiry.toString(),policyRow.get("ai_authorization_revision"));db.audit(a,"AI_WORK_AUTHORIZATION",id,Map.of(),Map.of("action",action,"scope",scope,"expiresAt",expiry.toString()),"开启限定自动授权");return Map.of("id",id,"version",1);});}
    @Transactional public Map<String,Object> revoke(Actor actor,String id,Map<String,Object> body,String key){Actor a=actors.locked(actor);Db.fields(body,"version");return keys.execute(a,"work.revoke:"+id,key,body,()->{Db.conflict(db.update("UPDATE ai_work_authorizations SET revoked_at=now(),version=version+1 WHERE company_id=? AND owner_id=? AND id=? AND version=? AND revoked_at IS NULL",a.company(),a.id(),id,Db.version(body)));db.audit(a,"AI_WORK_AUTHORIZATION_REVOKED",id,Map.of(),Map.of("revoked",true),"撤回限定自动授权");return Map.of("id",id,"revoked",true);});}
    public boolean preauthorized(Actor a,String action,Map<String,Object> payload,int batchSize){
        var row=authorizationPolicy.row(a,false);var policy=authorizationPolicy.rules(row);if(!policy.allows(action)||batchSize>policy.actions())return false;
        for(var r:db.rows("SELECT scope FROM ai_work_authorizations WHERE company_id=? AND owner_id=? AND action=? AND revoked_at IS NULL AND expires_at>now() AND policy_revision=?",a.company(),a.id(),action,row.get("ai_authorization_revision"))){var scope=db.read(r.get("scope"));int max=((Number)scope.getOrDefault("maxActions",5)).intValue();if(batchSize>max)continue;if(action.equals("CREATE_TASK")&&Business.strings(scope,"ownerIds").contains(Db.str(payload,"ownerId"))||action.equals("SUBMIT_DELIVERY")&&Business.strings(scope,"taskIds").contains(Db.str(payload,"taskId")))return true;}return false;
    }
    public void validatePlan(Actor a,Map<String,Object> p){validatePlan(a,p,null,false);}
    /** 在执行事务内只复核当前步骤；已完成动作的目标后续变化不阻塞其余动作。 */
    public void validateStep(Actor a,Map<String,Object> p,String step){validatePlan(a,p,Set.of(step),true);}
    /** 重规划只复用仍有效且业务内容/依据均相同的逐动作授权；过期和变化的动作重新确认。 */
    public boolean reusableAuthorization(Actor a,String id,int version,String action,Map<String,Object> payload,Map<String,Object> next){
        var p=repo.plan(a,id,version);var old=db.read(p.get("body"));if(!Objects.equals(old.get("sources"),next.get("sources")))return false;
        String hash=WorkActions.fingerprint(db,action,payload);
        for(var step:db.rows("SELECT step_key,payload FROM ai_work_steps WHERE company_id=? AND work_id=? AND plan_version=? AND action=? AND state<>'SUCCEEDED'",a.company(),id,version,action)){
            var previous=db.read(step.get("payload"));if(!hash.equals(WorkActions.fingerprint(db,action,previous)))continue;
            boolean allowed=Boolean.TRUE.equals(previous.get("explicit"))||Boolean.TRUE.equals(previous.get("confirmed"))||Boolean.TRUE.equals(previous.get("preauthorized"))&&preauthorized(a,action,payload,DeliveryService.maps(next,"actions").size());
            if(!allowed)continue;try{validatePlan(a,p,Set.of(Db.str(step,"step_key")),false);return true;}catch(ApiError e){return false;}
        }return false;
    }
    private void validatePlan(Actor a,Map<String,Object> p,Set<String> selected,boolean lock){
        if(!actors.fingerprint(a).equals(p.get("permission_fingerprint"))||!((java.sql.Timestamp)p.get("expires_at")).toInstant().isAfter(Instant.now()))throw new ApiError(409,"PLAN_STALE","办理条件已更新，请补充消息重新整理");
        var plan=new LinkedHashMap<>(db.read(p.get("body")));var actions=DeliveryService.maps(plan,"actions");var pending=new ArrayList<Map<String,Object>>();
        var finished=db.rows("SELECT step_key FROM ai_work_steps WHERE company_id=? AND work_id=? AND plan_version=? AND state IN ('SUCCEEDED','SKIPPED','CANCELLED')",a.company(),p.get("work_id"),p.get("version")).stream().map(r->Db.str(r,"step_key")).collect(java.util.stream.Collectors.toSet());
        for(int i=0;i<actions.size();i++){String key="action-"+(i+1);if(selected==null?!finished.contains(key):selected.contains(key))pending.add(actions.get(i));}
        plan.put("actions",pending);personnel.validate(a,plan);
        if(lock)procedures.lockForExecution(a,DeliveryService.maps(plan,"sources"));else procedures.validateForExecution(a,DeliveryService.maps(plan,"sources"));
        for(var action:pending){var payload=db.read(action.get("payload"));if(payload.get("taskId") instanceof String id){var task=TaskAccess.readable(db,a,id,lock);if(!Objects.equals(task.get("version"),payload.get("taskVersion")))throw ApiError.conflict();}
            for(var similar:DeliveryService.maps(action,"similarTasks")){var task=TaskAccess.readable(db,a,Db.str(similar,"id"),false);if(!Objects.equals(task.get("version"),similar.get("version")))throw ApiError.conflict();}}
        for(var file:DeliveryService.maps(plan,"fileHashes"))if(!AttachmentApplicationService.hash((byte[])attachments.owned(a,Db.str(file,"id")).get("data")).equals(file.get("hash")))throw ApiError.conflict();
    }
    private void validateInput(Actor a,WorkInput input){attachments.intake(a,input.attachments());if(input.answers().get("ownerId") instanceof String owner){var user=db.one("SELECT * FROM users WHERE company_id=? AND id=? AND status='ACTIVE'",a.company(),owner);if(!a.canSeeUser(user))throw ApiError.forbidden();}if(!input.taskId().isBlank()){var t=TaskAccess.readable(db,a,input.taskId(),false);if(((Number)t.get("version")).intValue()!=input.taskVersion())throw ApiError.conflict();}}
    private Map<String,Object> currentResult(Actor a,Map<String,Object> stored){
        var value=new LinkedHashMap<>(stored);if(!(value.get("taskId") instanceof String task))return value;
        try{TaskAccess.readable(db,a,task,false);if(value.containsKey("report")&&value.get("checkId") instanceof String check){var report=delivery.get(a,task,check);value.put("report",report);value.put("summary",report.get("summary"));}}
        catch(ApiError error){return Map.of("summary","你目前无法查看该任务或检查结果");}return value;
    }
    private void requireEnabled(){if(!enabled)throw new ApiError(503,"WORK_DISABLED","AI 办事暂时不可用，任务和日志仍可使用");}
}
